(async()=>{try{const u='https://api.github.com/repos/shinobione/risotools/contents/astea/shinoastea-pc-launcher.js?ref=main&t='+Date.now();const r=await fetch(u,{cache:'no-store',headers:{Accept:'application/vnd.github+json'}});if(!r.ok)throw Error('GitHub API '+r.status);const j=await r.json();if(!j.content)throw Error('Launcher PC absent');const b=atob(j.content.replace(/\s/g,'')),a=Uint8Array.from(b,c=>c.charCodeAt(0));eval(new TextDecoder().decode(a))}catch(e){alert('ShinoAstea PC bootstrap : '+e.message)}})();